// Command tokens generates the design tokens of the web UI and the terminal
// colors' default settings of the core from spec/tokens.json, the one
// place they are defined.
//
//	go run ./scripts/tokens           writes the generated files
//	go run ./scripts/tokens -check    writes nothing; fails if one is stale
//
// The output depends only on the tokens: names are written in sorted order.
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"go/format"
	"io"
	"math"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

const (
	source = "spec/tokens.json"
	cssOut = "web/src/tokens.css"
	goOut  = "internal/uisettings/tokens.go"
	header = "Generated by scripts/tokens from spec/tokens.json; do not edit."
)

// Color is an sRGB color with an alpha between 0 and 1. In the tokens it is
// "#rrggbb" or {"hex": "#rrggbb", "alpha": 0.5}.
type Color struct {
	RGB   uint32
	Alpha float64
}

var hexColor = regexp.MustCompile(`^#[0-9a-f]{6}$`)

func parseHex(s string) (uint32, error) {
	if !hexColor.MatchString(s) {
		return 0, fmt.Errorf("color %q is not #rrggbb in lower case", s)
	}
	v, err := strconv.ParseUint(s[1:], 16, 32)
	return uint32(v), err
}

func (c *Color) UnmarshalJSON(data []byte) error {
	var s string
	if json.Unmarshal(data, &s) == nil {
		rgb, err := parseHex(s)
		*c = Color{RGB: rgb, Alpha: 1}
		return err
	}
	var o struct {
		Hex   string   `json:"hex"`
		Alpha *float64 `json:"alpha"`
	}
	if err := strictUnmarshal(data, &o); err != nil {
		return fmt.Errorf("color %s is neither a string nor {hex, alpha}", bytes.TrimSpace(data))
	}
	rgb, err := parseHex(o.Hex)
	if err != nil {
		return err
	}
	if o.Alpha == nil || *o.Alpha < 0 || *o.Alpha > 1 {
		return fmt.Errorf("color %s needs an alpha between 0 and 1", bytes.TrimSpace(data))
	}
	*c = Color{RGB: rgb, Alpha: *o.Alpha}
	return nil
}

func (c Color) hex() string { return fmt.Sprintf("#%06x", c.RGB) }

func (c Color) css() string {
	if c.Alpha == 1 {
		return c.hex()
	}
	return fmt.Sprintf("rgba(%d, %d, %d, %s)", c.RGB>>16&0xff, c.RGB>>8&0xff, c.RGB&0xff, num(c.Alpha))
}

// Themed is a color of the interface in the light and the dark theme.
type Themed struct {
	Light Color `json:"light"`
	Dark  Color `json:"dark"`
}

func (t *Themed) UnmarshalJSON(data []byte) error {
	var o struct {
		Light *Color `json:"light"`
		Dark  *Color `json:"dark"`
	}
	if err := strictUnmarshal(data, &o); err != nil {
		return err
	}
	if o.Light == nil || o.Dark == nil {
		return errors.New("a color needs a light and a dark value")
	}
	*t = Themed{Light: *o.Light, Dark: *o.Dark}
	return nil
}

// Terminal is a terminal's default colors: the 16 ANSI colors are black to
// white, then their bright variants.
type Terminal struct {
	Background Color   `json:"background"`
	Foreground Color   `json:"foreground"`
	Cursor     Color   `json:"cursor"`
	Selection  Color   `json:"selection"`
	Palette    []Color `json:"palette"`
}

// Theme is a color theme the user chooses: the accent and the text on it.
// The neutrals (background, text, borders) are the same in every theme.
type Theme struct {
	ID       string  `json:"id"`
	Accent   *Themed `json:"accent"`
	OnAccent *Themed `json:"onAccent"`
}

// Tokens is spec/tokens.json.
type Tokens struct {
	Color  map[string]Themed `json:"color"`
	Status map[string]Themed `json:"status"`
	Git    map[string]Themed `json:"git"`
	Chart  map[string]Themed `json:"chart"`
	// FileIcon: the hues of file-type icons (web/src/fileIcons.tsx).
	FileIcon map[string]Themed `json:"fileIcon"`
	// Syntax: the colors of code by the role of a token (comment, keyword,
	// string…; web/src/highlight). Opaque, since the editor takes them as
	// they are.
	Syntax map[string]Themed `json:"syntax"`
	// Themes: the first is the default.
	Themes   []Theme `json:"themes"`
	Terminal struct {
		Light *Terminal `json:"light"`
		Dark  *Terminal `json:"dark"`
	} `json:"terminal"`
	// Metric: lengths that stay in CSS pixels.
	Metric map[string]float64 `json:"metric"`
	// Size: lengths of the chrome in CSS pixels at the root font size,
	// written in rem so that the UI font size setting scales them.
	Size map[string]float64 `json:"size"`
	Font struct {
		Root float64            `json:"root"`
		Size map[string]float64 `json:"size"`
	} `json:"font"`
}

func strictUnmarshal(data []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return err
	}
	if _, err := dec.Token(); err != io.EOF {
		return errors.New("data after the JSON value")
	}
	return nil
}

var tokenName = regexp.MustCompile(`^[a-z][a-zA-Z0-9]*$`)

// parse reads and validates the tokens.
func parse(data []byte) (*Tokens, error) {
	var t Tokens
	if err := strictUnmarshal(data, &t); err != nil {
		return nil, err
	}
	groups := map[string][]string{
		"color": keys(t.Color), "status": keys(t.Status), "git": keys(t.Git), "chart": keys(t.Chart), "fileIcon": keys(t.FileIcon),
		"syntax": keys(t.Syntax), "metric": keys(t.Metric), "size": keys(t.Size), "font.size": keys(t.Font.Size),
	}
	for _, group := range keys(groups) {
		if len(groups[group]) == 0 {
			return nil, fmt.Errorf("%s has no tokens", group)
		}
		for _, name := range groups[group] {
			if !tokenName.MatchString(name) {
				return nil, fmt.Errorf("%s.%s: names are camelCase letters and digits", group, name)
			}
		}
	}
	for name, c := range t.Syntax {
		if c.Light.Alpha != 1 || c.Dark.Alpha != 1 {
			return nil, fmt.Errorf("syntax.%s: syntax colors are opaque", name)
		}
	}
	for _, group := range []map[string]float64{t.Metric, t.Size, t.Font.Size} {
		for name, v := range group {
			if v <= 0 {
				return nil, fmt.Errorf("%s must be positive", name)
			}
		}
	}
	if t.Font.Root <= 0 {
		return nil, errors.New("font.root must be positive")
	}
	if len(t.Themes) == 0 {
		return nil, errors.New("themes has no themes")
	}
	seen := map[string]bool{}
	for _, th := range t.Themes {
		if !tokenName.MatchString(th.ID) || seen[th.ID] {
			return nil, fmt.Errorf("theme %q: ids are camelCase letters and digits, each once", th.ID)
		}
		seen[th.ID] = true
		if th.Accent == nil || th.OnAccent == nil {
			return nil, fmt.Errorf("theme %s needs accent and onAccent", th.ID)
		}
	}
	for name, term := range map[string]*Terminal{"light": t.Terminal.Light, "dark": t.Terminal.Dark} {
		if term == nil {
			return nil, fmt.Errorf("terminal.%s is missing", name)
		}
		if len(term.Palette) != 16 {
			return nil, fmt.Errorf("terminal.%s.palette has %d colors, not 16", name, len(term.Palette))
		}
		for _, c := range append([]Color{term.Background, term.Foreground, term.Cursor, term.Selection}, term.Palette...) {
			if c.Alpha != 1 {
				return nil, fmt.Errorf("terminal.%s: terminal colors are opaque", name)
			}
		}
	}
	return &t, nil
}

func keys[V any](m map[string]V) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// num writes a number without a trailing ".0" or exponent.
func num(v float64) string { return strconv.FormatFloat(v, 'f', -1, 64) }

// kebab turns a camelCase name into kebab-case.
func kebab(s string) string {
	var b strings.Builder
	for i, r := range s {
		if r >= 'A' && r <= 'Z' {
			if i > 0 {
				b.WriteByte('-')
			}
			r += 'a' - 'A'
		}
		b.WriteRune(r)
	}
	return b.String()
}

// rem writes a length in CSS pixels at the root font size in rem.
func rem(px, root float64) string {
	return strconv.FormatFloat(math.Round(px/root*10000)/10000, 'f', -1, 64) + "rem"
}

// css renders web/src/tokens.css in the form Prettier keeps. The dark
// theme is the default and <html data-theme="light"> selects the light
// one, as in web/src/styles/base.css; <html data-accent="id"> selects a color
// theme other than the first.
func css(t *Tokens) []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, "/* %s */\n", header)
	pick := func(c Themed, light bool) Color {
		if light {
			return c.Light
		}
		return c.Dark
	}
	accent := func(th Theme, light bool) {
		fmt.Fprintf(&b, "  --ds-accent: %s;\n", pick(*th.Accent, light).css())
		fmt.Fprintf(&b, "  --ds-on-accent: %s;\n", pick(*th.OnAccent, light).css())
	}
	block := func(selector string, light bool) {
		fmt.Fprintf(&b, "%s {\n", selector)
		accent(t.Themes[0], light)
		for _, g := range []struct {
			prefix string
			colors map[string]Themed
		}{{"color", t.Color}, {"status", t.Status}, {"git", t.Git}, {"chart", t.Chart}, {"file-icon", t.FileIcon}, {"syntax", t.Syntax}} {
			for _, name := range keys(g.colors) {
				fmt.Fprintf(&b, "  --ds-%s-%s: %s;\n", g.prefix, kebab(name), pick(g.colors[name], light).css())
			}
		}
		term := t.Terminal.Dark
		if light {
			term = t.Terminal.Light
		}
		fmt.Fprintf(&b, "  --ds-terminal-background: %s;\n", term.Background.css())
		fmt.Fprintf(&b, "  --ds-terminal-foreground: %s;\n", term.Foreground.css())
		fmt.Fprintf(&b, "  --ds-terminal-cursor: %s;\n", term.Cursor.css())
		fmt.Fprintf(&b, "  --ds-terminal-selection: %s;\n", term.Selection.css())
		for i, c := range term.Palette {
			fmt.Fprintf(&b, "  --ds-terminal-ansi-%d: %s;\n", i, c.css())
		}
		if !light {
			// Lengths do not change with the theme.
			for _, name := range keys(t.Metric) {
				fmt.Fprintf(&b, "  --ds-metric-%s: %spx;\n", kebab(name), num(t.Metric[name]))
			}
			for _, name := range keys(t.Size) {
				fmt.Fprintf(&b, "  --ds-size-%s: %s;\n", kebab(name), rem(t.Size[name], t.Font.Root))
			}
			for _, name := range keys(t.Font.Size) {
				fmt.Fprintf(&b, "  --ds-font-size-%s: %s;\n", kebab(name), rem(t.Font.Size[name], t.Font.Root))
			}
		}
		b.WriteString("}\n")
	}
	block(":root", false)
	block(":root[data-theme='light']", true)
	// The other themes: their dark accent, then their light one, which is
	// more specific than both the dark one and the light theme's default.
	for _, th := range t.Themes[1:] {
		fmt.Fprintf(&b, ":root[data-accent='%s'] {\n", th.ID)
		accent(th, false)
		b.WriteString("}\n")
		fmt.Fprintf(&b, ":root[data-accent='%s'][data-theme='light'] {\n", th.ID)
		accent(th, true)
		b.WriteString("}\n")
	}
	return b.Bytes()
}

// golang renders internal/uisettings/tokens.go: the terminal colors that
// are the defaults of the terminal.colors.* settings.
func golang(t *Tokens) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, "// %s\n\npackage uisettings\n\n", header)
	b.WriteString("// tokenColors are the terminal's default colors in the dark and the light theme.\n")
	b.WriteString("var tokenColors = map[string]terminalColors{\n")
	for _, name := range []string{"dark", "light"} {
		term := t.Terminal.Dark
		if name == "light" {
			term = t.Terminal.Light
		}
		fmt.Fprintf(&b, "%q: {\nBackground: %q, Foreground: %q, Cursor: %q, Selection: %q,\nPalette: []string{\n",
			name, term.Background.hex(), term.Foreground.hex(), term.Cursor.hex(), term.Selection.hex())
		for i := 0; i < 16; i += 8 {
			for _, c := range term.Palette[i : i+8] {
				fmt.Fprintf(&b, "%q, ", c.hex())
			}
			b.WriteString("\n")
		}
		b.WriteString("},\n},\n")
	}
	b.WriteString("}\n\n")
	b.WriteString("// tokenThemes are the color themes, the default first.\n")
	b.WriteString("var tokenThemes = []string{")
	for i, th := range t.Themes {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(&b, "%q", th.ID)
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

// generate returns the generated files by their path under the repository.
func generate(data []byte) (map[string][]byte, error) {
	t, err := parse(data)
	if err != nil {
		return nil, err
	}
	g, err := golang(t)
	if err != nil {
		return nil, err
	}
	return map[string][]byte{cssOut: css(t), goOut: g}, nil
}

// run generates the files under root; with check it writes nothing and
// reports the files that differ from what would be generated.
func run(root string, check bool) error {
	data, err := os.ReadFile(filepath.Join(root, source))
	if err != nil {
		return err
	}
	files, err := generate(data)
	if err != nil {
		return fmt.Errorf("%s: %w", source, err)
	}
	var stale []string
	for _, name := range keys(files) {
		path := filepath.Join(root, name)
		if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, files[name]) {
			continue
		}
		if check {
			stale = append(stale, name)
			continue
		}
		if err := os.WriteFile(path, files[name], 0o644); err != nil {
			return err
		}
	}
	if len(stale) > 0 {
		return fmt.Errorf("stale: %s (run `make tokens`)", strings.Join(stale, ", "))
	}
	return nil
}

func main() {
	check := flag.Bool("check", false, "write nothing; fail if a generated file is stale")
	root := flag.String("root", ".", "the repository")
	flag.Parse()
	if err := run(*root, *check); err != nil {
		fmt.Fprintln(os.Stderr, "tokens:", err)
		os.Exit(1)
	}
}
